add('07_states','Состояния запуска: частичный результат не маскируется',[
('draft','created'),('queue','queued'),('run','running'),('wait','waiting_input'),('retry','retry_scheduled'),('unknown','needs_reconciliation'),('done','succeeded'),('partial','partial'),('failed','failed'),('cancel','cancelled')],
[('draft','queue','проверены предусловия'),('queue','run','lease'),('run','wait','нужны сведения'),('wait','queue','новая разрешённая попытка'),('run','retry','временная безопасная ошибка'),('retry','queue','backoff'),('run','unknown','исход внешнего действия неизвестен'),('unknown','queue','подтверждён безопасный повтор'),('run','done','все обязательные шаги'),('run','partial','разрешены неполные выходы'),('run','failed','неустранимая ошибка'),('queue','cancel','отмена'),('run','cancel','отмена подтверждена')],'''stateDiagram-v2
  [*] --> created
  created --> queued: предусловия приняты
  queued --> running: получен lease
  running --> waiting_input: отсутствуют сведения
  waiting_input --> queued: разрешено продолжение
  running --> retry_scheduled: безопасный временный сбой
  retry_scheduled --> queued: backoff
  running --> needs_reconciliation: внешний исход неизвестен
  needs_reconciliation --> queued: безопасный повтор подтверждён
  running --> succeeded: обязательные шаги выполнены
  running --> partial: допустим неполный результат
  running --> failed: неустранимый сбой
  queued --> cancelled: отмена
  running --> cancelled: отмена подтверждена
''')
